 if(destination.startsWith('drowned-')){floorOne=null;floorTwo=null;collector=null;clockmaker=null;drowned=newDrownedRun();drowned.phase=destination==='drowned-furniture'?2:destination==='drowned-maintenance'?3:destination==='drowned-basin'?4:destination==='drowned-chase'?5:destination==='drowned-bulkhead'?6:1;drowned.pumps=Array.from({length:Math.min(4,Math.max(0,drowned.phase-1))},(_,index)=>index);if(drowned.phase>=3){drowned.channels=[1,2,0];drowned.channelSolved=true}if(drowned.phase>=5)drowned.sluices=[0,1];saveDrowned();return startDrowned(false)}
