const ADMIN_DESTINATION_LABELS={'floor5-entry':'Floor 5 · Room 501','floor5-library':'Floor 5 · Room 525 Library','floor5-boss':'Floor 5 · Room 550 Elevator Boss','floor1-entry':'Floor 1 · Room 1','floor1-sound':'Floor 1 · Room 10 Sound Sector','floor1-ballroom':'Floor 1 · Room 40 Ballroom','floor1-chef':'Chef Arena · Phase One','floor1-chef-freezer':'Chef Arena · Phase Two','floor1-chef-final':'Chef Arena · Phase Three','floor1-chef-elevator':'Chef Arena · Defeated / Elevator','floor2-outside':'Floor 2 · Room 115 Ballroom','floor2-watcher':'Floor 2 · Room 116 Watcher','floor2-fireescape':'Floor 2 · Rooms 117–118 Fire Escapes','floor2-garden':'Floor 2 · Room 119 Garden Maze','floor2-window':'Floor 2 · Room 120 Window Creature','floor2-guests':'Floor 2 · Room 121 False Guests','floor2-fuse':'Floor 2 · Room 122 Fuse Box','floor2-rooftops':'Floor 2 · Rooms 123–129 Rooftops','floor2-spotlights':'Floor 2 · Room 130 Spotlights','floor2-gauntlet':'Floor 2 · Rooms 131–139 Exterior','floor2-crane':'Floor 2 · Room 140 Crane','room140':'Floor 2 · Room 150 Safe Vault','molly-electrical':'Molly · Electrical Section'};
const ADMIN_LOCATION_CATEGORIES=[['hotel','HOTEL & LOBBY'],['floor5','FLOOR 5'],['floor1','FLOOR 1'],['floor2','FLOOR 2'],['boss','BOSS ENCOUNTERS'],['pursuer','PURSUER CHASES'],['subfloor','SUB-FLOORS'],['cabin','CABIN'],['jailbreak','JAILBREAK']];
const ADMIN_BOSS_MONSTERS=new Set(['chef','collector','clockmaker','drowned-guest','pursuer','molly','luggage-warden','empty-porter','black-bellhop','reflection','hotel-manager','night-auditor']);
const ADMIN_FLOOR_TWO_MONSTERS=new Set(['ballroom-guest','watcher','gardener','window-creature','false-guest']);
const ADMIN_CABIN_MONSTERS=new Set(['spider','root']);
let adminDestinationOptions=[];
function adminDestinationCategory(id){if(id.startsWith('cabin-'))return'cabin';if(id.startsWith('jailbreak-'))return'jailbreak';if(id==='badge-sunroom'||id.startsWith('cinema-'))return'subfloor';if(id.startsWith('pursuer-'))return'pursuer';if(id.startsWith('collector-')||id.startsWith('clock-')||id.startsWith('drowned-')||id.startsWith('floor1-chef')||id==='floor5-boss'||id==='molly-electrical')return'boss';if(id.startsWith('floor5-'))return'floor5';if(id.startsWith('floor1-'))return'floor1';if(id.startsWith('floor2-')||id==='room140')return'floor2';return'hotel'}
function adminEncounterCategory(id){if(ADMIN_BOSS_MONSTERS.has(id))return'boss';if(ADMIN_FLOOR_TWO_MONSTERS.has(id))return'floor2';if(ADMIN_CABIN_MONSTERS.has(id))return'cabin';return'monster'}
function refreshAdminTeleportLabels(){const select=document.querySelector('#admin-teleport');for(const option of select?.options||[])if(ADMIN_DESTINATION_LABELS[option.value])option.textContent=ADMIN_DESTINATION_LABELS[option.value]}
function refreshAdminMonsterLabels(){const select=document.querySelector('#admin-monster');for(const option of select?.options||[]){const config=ADMIN_MONSTER_CATALOG[option.value],copy=config&&ADMIN_MONSTER_BEHAVIOR_COPY[config.behavior];if(!copy)continue;option.dataset.pattern=copy;option.title=copy}}
function updateAdminLocationDetail(){const select=document.querySelector('#admin-teleport'),detail=document.querySelector('#admin-location-detail'),option=select?.selectedOptions?.[0];if(!detail||!option)return;const category=ADMIN_LOCATION_CATEGORIES.find(([id])=>id===adminDestinationCategory(option.value))?.[1]||'LOCATION';detail.textContent=`${category} · ${option.textContent.toUpperCase()}`}
function updateAdminMonsterDetail(){const select=document.querySelector('#admin-monster'),detail=document.querySelector('#admin-monster-detail'),id=select?.value,config=ADMIN_MONSTER_CATALOG[id];if(!detail||!config)return;const category=adminEncounterCategory(id)==='boss'?'BOSS':adminEncounterCategory(id)==='floor2'?'FLOOR 2 MONSTER':adminEncounterCategory(id)==='cabin'?'CABIN MONSTER':'RANDOM MONSTER',behavior=ADMIN_MONSTER_BEHAVIOR_COPY[config.behavior]||config.behavior;detail.textContent=`${category} · ${config.name.toUpperCase()} · ${behavior.toUpperCase()} · ${config.phaseWalls?'PHASES THROUGH WALLS':'SOLID WALLS'}`}
function adminSetStatus(message,state='success'){const status=document.querySelector('#admin-status');if(status){status.textContent=message;status.dataset.state=state}return message}
function runAdminCommand(label,action){try{const result=action();adminSetStatus(`${label} · COMPLETE`);return result}catch(error){console.error(`Admin command failed: ${label}`,error);adminSetStatus(`${label} · ${String(error?.message||error).toUpperCase()}`,'error');document.querySelector('#prompt').textContent=`ADMIN ERROR · ${label}`;return null}}
function openAdminPanel(){refreshAdminMonsterLabels();updateAdminLocationDetail();updateAdminMonsterDetail();const panel=document.querySelector('#admin-panel'),toggle=document.querySelector('#admin-toggle');panel.hidden=false;toggle.setAttribute('aria-expanded','true');document.body.classList.add('admin-open');controls.unlock()}
