 panel.addEventListener('click',event=>event.stopPropagation());document.addEventListener('keydown',event=>{if(event.code!=='F2'||event.repeat)return;event.preventDefault();panel.hidden?openAdminPanel():closeAdminPanel()});let lastMonsterTick=performance.now();setInterval(()=>{const now=performance.now(),dt=Math.min(.1,(now-lastMonsterTick)/1000);lastMonsterTick=now;updateAdminMonsters(dt,now*.001)},50);
 document.querySelector('#admin-ransack').onclick=()=>runAdminCommand('TRIGGER RANSACK',()=>{closeAdminPanel();finishRansackEvent(false);ransack.cooldown=0;startRansackEvent(true);return true});setupGraphicsControls();adminSetStatus('ADMIN READY','success')
